package com.sky.controller.admin;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import com.sky.result.Result;
import com.sky.service.DishService;
import org.springframework.data.redis.core.RedisTemplate;

@ExtendWith(MockitoExtension.class)
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    @Test
    @DisplayName("正向测试：正常输入时方法能正确执行并返回成功")
    void testStartOrStop_Success() {
        // Arrange
        Integer status = 1;
        Long id = 1L;
        Set<String> cacheKeys = Collections.singleton("dish_1");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode(), "返回码应为1表示成功");
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(cacheKeys);
    }

    @Test
    @DisplayName("边界测试：修复后路径变量正确绑定，不再抛出MissingPathVariableException")
    void testStartOrStop_PathVariableFixed() {
        // Arrange: 测试不同status值，验证方法能正常处理
        Integer status0 = 0;
        Long id = 2L;
        Set<String> cacheKeys = Collections.singleton("dish_2");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act: 调用方法，修复后应能正确绑定status1到status参数
        Result<String> result = dishController.startOrStop(status0, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());
        verify(dishService).startOrStop(status0, id);
    }

    @Test
    @DisplayName("验证修复后的空值/null处理：status为null时方法能正常执行")
    void testStartOrStop_NullStatus() {
        // Arrange
        Integer status = null;
        Long id = 3L;
        Set<String> cacheKeys = Collections.emptySet();
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(0L);

        // Act: 即使status为null，方法也应能处理（假设service层能处理）
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());
        verify(dishService).startOrStop(status, id);
    }

    @Test
    @DisplayName("验证修复后的空值/null处理：id为null时方法能正常执行")
    void testStartOrStop_NullId() {
        // Arrange
        Integer status = 1;
        Long id = null;
        Set<String> cacheKeys = Collections.emptySet();
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(0L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());
        verify(dishService).startOrStop(status, id);
    }
}
